/**
 * Account / feedback related types.
 *
 * Currently only the feedback submission API needs these. Other account
 * operations (login/logout/status/...) are exposed via the CLI directly and
 * do not need typed wrappers in this SDK yet.
 */
/**
 * Result of the feedback submission operation.
 */
export interface FeedbackResult {
    success: boolean;
    message: string;
    /** Server-side request id, returned on successful submission */
    requestId?: string;
}